.atmr-button {
  background-color: transparent;
  padding: 0;
  text-decoration: none;
  border-radius: inherit;
  border: 2px solid transparent;
  box-sizing: border-box;
  outline: none;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  max-width: 100%;
  white-space: nowrap;
  position: relative;
}
.atmr-button:before {
  box-sizing: border-box;
  content: "";
  display: none;
  position: absolute;
  pointer-events: none;
  top: -2px;
  left: -2px;
  right: -2px;
  bottom: -2px;
  z-index: 100;
  border-radius: inherit;
  outline: var(--atmr-focus-contrast-extra-border-width) solid var(--atmr-focus-contrast-extra-color);
}
.atmr-button:focus-within::before {
  display: none;
}
.atmr-button:focus-visible::before, .atmr-button:has(:focus-visible)::before {
  display: block;
}
.atmr-button:focus-within {
  outline: none;
}
.atmr-button:focus-visible, .atmr-button:has(:focus-visible) {
  outline: var(--atmr-focus-contrast-border-width) solid var(--atmr-focus-contrast-color);
  outline-offset: var(--atmr-focus-contrast-extra-border-width);
}
.atmr-button {
  padding: 0;
  margin: 0;
  box-sizing: border-box;
}
.atmr-button * {
  padding: 0;
  margin: 0;
  box-sizing: border-box;
}
.atmr-button svg {
  flex-shrink: 0;
}
.atmr-button .atmr-button__text {
  display: inline-block;
  text-overflow: ellipsis;
  overflow: hidden;
}
